// SameSite controls when the browser sends cookies on cross-site requests

// SameSite=Strict: cookie NEVER sent on cross-site requests
// User clicks a link from evil.com to bank.com → no cookie sent
// Breaks OAuth flows, 'Share this article' links, some payment flows
res.cookie('sessionId', token, {
  httpOnly: true,
  secure: true,
  sameSite: 'strict',
});

// SameSite=Lax (default in modern browsers): cookie sent on
// top-level navigation (clicking a link) but NOT on cross-site POST/PUT/DELETE
// Protects against CSRF form submissions while allowing OAuth redirects
// Recommended for most apps
res.cookie('sessionId', token, {
  httpOnly: true,
  secure: true,
  sameSite: 'lax',  // ← This alone defeats most CSRF attacks
});

// SameSite=None: cookie always sent (required for embeds, iframes)
// MUST be paired with Secure: true (HTTPS only)
// Vulnerable to CSRF — requires CSRF token if used
res.cookie('sessionId', token, {
  httpOnly: true,
  secure: true,
  sameSite: 'none',  // Only use when embedding is required
});

// WHY SameSite=Lax defeats the attack above:
// evil.com submits a form via POST to bank.com
// Browser checks: is this a cross-site POST? Yes.
// SameSite=Lax? Don't attach the session cookie.
// bank.com receives the request with no session → unauthenticated → rejected

import crypto from 'crypto';

// CSRF token: a random value stored in the session and embedded in forms
// The attacker on evil.com cannot read the token (SOP prevents it)
// So they can't include a valid token in their forged request

// Generate and store token in session
app.use((req, res, next) => {
  if (!req.session.csrfToken) {
    req.session.csrfToken = crypto.randomBytes(32).toString('hex');
  }
  next();
});

// Include token in every HTML form
app.get('/transfer', (req, res) => {
  res.send(`
    <form method="POST" action="/transfer">
      <input type="hidden" name="_csrf" value="${req.session.csrfToken}" />
      <input name="amount" />
      <button>Transfer</button>
    </form>
  `);
});

// Validate token on every state-changing request
app.post('/transfer', (req, res) => {
  const { _csrf, amount, to_account } = req.body;

  // Constant-time comparison (prevents timing attacks)
  if (!_csrf || !crypto.timingSafeEqual(
    Buffer.from(_csrf),
    Buffer.from(req.session.csrfToken)
  )) {
    return res.status(403).json({ error: 'Invalid CSRF token' });
  }

  // Process the transfer
});

// For SPAs: use the Double Submit Cookie pattern or a custom header
// Custom header approach (axios/fetch always set custom headers, but forms can't):
app.post('/api/transfer', (req, res) => {
  // A cross-site form POST cannot set custom headers
  // A same-origin fetch() can set custom headers
  if (!req.headers['x-requested-with']) {
    return res.status(403).json({ error: 'CSRF check failed' });
  }
});
